function getLocalMockTest(topic, count) {
	const normTopic = topic.toLowerCase().trim();
	let questions = [];
	if (normTopic.includes("react") || normTopic.includes("frontend") || normTopic.includes("web")) questions = [...LOCAL_MOCK_TESTS["react"]];
	else if (normTopic.includes("python") || normTopic.includes("software") || normTopic.includes("developer")) questions = [...LOCAL_MOCK_TESTS["python"]];
	else if (normTopic.includes("sql") || normTopic.includes("database") || normTopic.includes("data")) questions = [...LOCAL_MOCK_TESTS["sql"]];
	else questions = [...LOCAL_MOCK_TESTS["general"]];
	while (questions.length < count) questions = [...questions, ...questions];
	return questions.slice(0, count).map((q, idx) => ({
		...q,
		topic: `${q.topic} - Q${idx + 1}`
	}));
}
